import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`sponsor-sourcing`,heroTitle:e({defaultMessage:`Land your next sponsor in minutes`,id:`e85625fe27`}),heroSubtitle:e({defaultMessage:`Perplexity Computer analyzes your content, finds competing sponsors, and drafts outreach emails — automatically.`,id:`931afdfce1`}),heroCta:e({defaultMessage:`Find my sponsors`,id:`1ec1271d55`}),inputUrlCta:e({defaultMessage:`Find potential sponsors`,id:`95751981cc`}),inputUrlPlaceholder:`e.g. instagram.com/yourchannel`,inputUrlPrefill:e({defaultMessage:`Go to {url} and analyze my recent posts, content style, audience, and engagement. Then find 10 similar creators in my niche who have a larger following. For each creator, extract every brand or company that has sponsored their posts. Finally, draft a personalized cold outreach email to each sponsor explaining who I am, why my audience is a fit, and asking if they'd be interested in a sponsorship collaboration. Deliver: 1) A profile summary of my account. 2) A list of 10 competing creators with follower counts. 3) A list of every sponsor extracted from those creators. 4) A personalized outreach email draft for each sponsor.`,id:`fcc2aa35a7`}),heroOverlaySteps:[e({defaultMessage:`Analyzing your profile, content style, and audience demographics`,id:`80a7d5f238`}),e({defaultMessage:`Finding 10 similar creators in your niche with larger followings`,id:`db4ffe78c4`}),e({defaultMessage:`Extracting every brand sponsorship from competing creators’ posts`,id:`0a24e4d04d`}),e({defaultMessage:`Personalized outreach emails for each sponsor — ready to send`,id:`be371ae3bb`})],generatingSteps:[e({defaultMessage:`Visiting {url} to extract your content style, niche, and engagement metrics`,id:`07920c3702`}),e({defaultMessage:`Designing an agent to discover competing creators and extract their brand sponsors`,id:`44629d4c11`}),e({defaultMessage:`Configuring personalized email drafts tailored to each sponsor’s brand and your audience`,id:`e1d7ff70f2`}),e({defaultMessage:`Setting up deliverables — creator comparisons, sponsor lists, and outreach emails`,id:`84ce8a6bf1`})],featureSectionTitle:e({defaultMessage:`From profile to pitch`,id:`3f87c9abdb`}),featureCardTitles:[e({defaultMessage:`Connects to your creator stack`,id:`9b0aad7950`}),e({defaultMessage:`Outputs you can send`,id:`738b082634`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`b525df7deb`}),e({defaultMessage:`Gmail, Google Sheets, Notion, QuickBooks — Computer integrates with your stack so sponsor research and outreach happen in one workflow.`,id:`6ca5d9b489`}),e({defaultMessage:`Competitor breakdowns. Sponsor contact lists. Personalized pitch emails. Computer delivers ready-to-send outreach backed by real data from your niche.`,id:`bc9fb7c1e3`})],capabilitySectionTitle:e({defaultMessage:`Your sponsorship team, on autopilot`,id:`149a1c293b`}),capabilitySectionSubtitle:e({defaultMessage:`Drop your profile link, step away, come back to a full sponsor pipeline.`,id:`a846265e80`}),capabilityCards:[{title:e({defaultMessage:`Profile Analysis`,id:`8f93516c69`}),description:e({defaultMessage:`Computer can analyze your posts, engagement rate, audience demographics, and content themes — and summarize exactly what makes your profile attractive to sponsors.`,id:`57e629057e`})},{title:e({defaultMessage:`Competitor Discovery`,id:`c490c7d539`}),description:e({defaultMessage:`Computer can find creators in your niche with larger followings and surface the brands paying them — so you know exactly who to pitch.`,id:`e7468d0b97`})},{title:e({defaultMessage:`Outreach Drafting`,id:`74f6edbf5a`}),description:e({defaultMessage:`Computer can write personalized cold emails to each sponsor — referencing their past campaigns, your audience overlap, and a clear value proposition.`,id:`5a451460b7`})},{title:e({defaultMessage:`Connect Your Tools`,id:`fc147edc83`}),description:e({defaultMessage:`Computer can read and write to Gmail, Google Sheets, Notion, and more — build workflows that go from research to sent pitch in one step.`,id:`b654982096`})},{title:e({defaultMessage:`Remember & Learn`,id:`fc5286e544`}),description:e({defaultMessage:`Computer can remember your niche, past sponsors, and preferred pitch style across sessions — so every outreach round gets sharper.`,id:`572e6ed1e1`})},{title:e({defaultMessage:`Monitor & Alert`,id:`77fe250cb4`}),description:e({defaultMessage:`Computer can watch competing creators for new sponsorship posts and alert you when a brand starts spending in your niche.`,id:`bb6f7d201d`})}]});export{n as default};
